@RunWith(MockitoJUnitRunner.class)
public class AbstractCommandLineRunner_setRunOptions_TriageGen2Test {

    @Spy
    private AbstractCommandLineRunner runner;

    @Mock
    private CommandLineConfig config;

    @Mock
    private CompilerOptions options;

    @Mock
    private DiagnosticGroups diagnosticGroups;

    @Before
    public void setUp() throws IOException {
        // Setup default config values to avoid NullPointerExceptions
        doReturn(config).when(runner).getCommandLineConfig();
        doReturn(diagnosticGroups).when(runner).getDiagnosticGroups();

        // Default mock behaviors for config fields
        when(config.jscompError).thenReturn(CheckLevel.ERROR);
        when(config.jscompWarning).thenReturn(CheckLevel.WARNING);
        when(config.jscompOff).thenReturn(CheckLevel.OFF);
        when(config.define).thenReturn(Collections.emptyList());
        when(config.tweak).thenReturn(Collections.emptyList());
        when(config.tweakProcessing).thenReturn(false);
        when(config.manageClosureDependencies).thenReturn(false);
        when(config.closureEntryPoints).thenReturn(Collections.emptyList());
        when(config.jscompDevMode).thenReturn(false);
        when(config.codingConvention).thenReturn(null);
        when(config.summaryDetailLevel).thenReturn(null);
        when(config.jsOutputFile).thenReturn("");
        when(config.createSourceMap).thenReturn("");
        when(config.sourceMapDetailLevel).thenReturn(null);
        when(config.sourceMapFormat).thenReturn(null);
        when(config.variableMapInputFile).thenReturn("");
        when(config.propertyMapInputFile).thenReturn("");
        when(config.languageIn).thenReturn("");
        when(config.acceptConstKeyword).thenReturn(false);
    }

    @Test
    public void testSetRunOptions_BasicFlow() throws FlagUsageException, IOException {
        when(config.jsOutputFile).thenReturn("out.js");
        when(config.createSourceMap).thenReturn("map.js");
        when(config.languageIn).thenReturn("ES6"); // Should hit the 'else' in language check if not matched, but we need to test specific paths

        // We use a mock for VariableMap.load if possible, but since it is static, 
        // we ensure the path is not triggered by keeping strings empty.

        runner.setRunOptions(options);

        verify(diagnosticGroups).setWarningLevels(options, CheckLevel.ERROR, CheckLevel.ERROR);
        verify(diagnosticGroups).setWarningLevels(options, CheckLevel.WARNING, CheckLevel.WARNING);
        verify(diagnosticGroups).setWarningLevels(options, CheckLevel.OFF, CheckLevel.OFF);

        assertThat(options.jsOutputFile).isEqualTo("out.js");
        assertThat(options.sourceMapOutputPath).isEqualTo("map.js");
    }

    @Test
    public void testSetRunOptions_ClosureDependencies() throws FlagUsageException, IOException {
        when(config.closureEntryPoints).thenReturn(Collections.singletonList("entry.js"));

        runner.setRunOptions(options);

        verify(options).setManageClosureDependencies(Collections.singletonList("entry.js"));
    }

    @Test
    public void testSetRunOptions_Languages() throws FlagUsageException, IOException {
        // Test ES5 Strict
        when(config.languageIn).thenReturn("ECMASCRIPT5_STRICT");
        runner.setRunOptions(options);
        verify(options).setLanguageIn(CompilerOptions.LanguageMode.ECMASCRIPT5);

        // Test ES5
        when(config.languageIn).thenReturn("ES5");
        runner.setRunOptions(options);
        verify(options, org.mockito.Mockito.atLeastOnce()).setLanguageIn(CompilerOptions.LanguageMode.ECMASCRIPT5);

        // Test ES3
        when(config.languageIn).thenReturn("ES3");
        runner.setRunOptions(options);
        verify(options, org.mockito.Mockito.atLeastOnce()).setLanguageIn(CompilerOptions.LanguageMode.ECMASCRIPT3);
    }

    @Test(expected = FlagUsageException.class)
    public void testSetRunOptions_UnknownLanguage() throws FlagUsageException, IOException {
        when(config.languageIn).thenReturn("UNKNOWN_LANG");
        runner.setRunOptions(options);
    }

    @Test
    public void testSetRunOptions_FullConfig() throws FlagUsageException, IOException {
        when(config.jscompDevMode).thenReturn(true);
        when(config.acceptConstKeyword).thenReturn(true);
        when(config.tweakProcessing).thenReturn(true);

        runner.setRunOptions(options);

        assertThat(options.devMode).isTrue();
        assertThat(options.acceptConstKeyword).isTrue();
        assertThat(options.tweakProcessing).isTrue();
    }

    /**
     * Note: Testing VariableMap.load(String) requires PowerMock or similar for static mocking.
     * Since this is a standard JUnit 4 environment, we focus on the logic branches 
     * reachable via standard Mockito.
     */
}
